use std::io::{self, BufRead, Write};

struct Node {
    key: i64,
    l: Option<Box<Node>>,
    r: Option<Box<Node>>,
}

fn insert(n: &mut Option<Box<Node>>, k: i64) -> bool {
    match n {
        None => {
            *n = Some(Box::new(Node { key: k, l: None, r: None }));
            true
        }
        Some(b) => {
            if k < b.key {
                insert(&mut b.l, k)
            } else if k > b.key {
                insert(&mut b.r, k)
            } else {
                false
            }
        }
    }
}

fn contains(n: &Option<Box<Node>>, k: i64) -> bool {
    let mut cur = n;
    while let Some(b) = cur {
        if k < b.key {
            cur = &b.l;
        } else if k > b.key {
            cur = &b.r;
        } else {
            return true;
        }
    }
    false
}

fn take_min(n: &mut Option<Box<Node>>) -> i64 {
    if n.as_ref().unwrap().l.is_some() {
        take_min(&mut n.as_mut().unwrap().l)
    } else {
        let b = n.take().unwrap();
        *n = b.r;
        b.key
    }
}

fn delete(n: &mut Option<Box<Node>>, k: i64) -> bool {
    match n {
        None => false,
        Some(b) => {
            if k < b.key {
                delete(&mut b.l, k)
            } else if k > b.key {
                delete(&mut b.r, k)
            } else {
                if b.l.is_none() {
                    let r = b.r.take();
                    *n = r;
                } else if b.r.is_none() {
                    let l = b.l.take();
                    *n = l;
                } else {
                    b.key = take_min(&mut b.r);
                }
                true
            }
        }
    }
}

fn inorder(n: &Option<Box<Node>>, out: &mut Vec<String>) {
    if let Some(b) = n {
        inorder(&b.l, out);
        out.push(b.key.to_string());
        inorder(&b.r, out);
    }
}

fn height(n: &Option<Box<Node>>) -> usize {
    match n {
        None => 0,
        Some(b) => 1 + height(&b.l).max(height(&b.r)),
    }
}

fn main() {
    let stdin = io::stdin();
    let mut o = io::stdout().lock();
    let mut root: Option<Box<Node>> = None;
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let mut it = line.split_whitespace();
        let cmd = match it.next() {
            Some(c) => c,
            None => continue,
        };
        let arg: i64 = it.next().and_then(|s| s.parse().ok()).unwrap_or(0);
        match cmd {
            "insert" => {
                writeln!(o, "{}", if insert(&mut root, arg) { "ok" } else { "dup" }).unwrap()
            }
            "contains" => {
                writeln!(o, "{}", if contains(&root, arg) { "yes" } else { "no" }).unwrap()
            }
            "delete" => {
                writeln!(o, "{}", if delete(&mut root, arg) { "ok" } else { "missing" }).unwrap()
            }
            "inorder" => {
                let mut v = Vec::new();
                inorder(&root, &mut v);
                if v.is_empty() {
                    writeln!(o, "<empty>").unwrap();
                } else {
                    writeln!(o, "{}", v.join(" ")).unwrap();
                }
            }
            "height" => writeln!(o, "{}", height(&root)).unwrap(),
            "min" | "max" => {
                let mut cur = &root;
                if cur.is_none() {
                    writeln!(o, "empty").unwrap();
                } else {
                    let mut key = 0;
                    while let Some(b) = cur {
                        key = b.key;
                        cur = if cmd == "min" { &b.l } else { &b.r };
                    }
                    writeln!(o, "{}", key).unwrap();
                }
            }
            _ => {}
        }
    }
}

